using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using LighFight.Runtime;using LighFight.Core;
public sealed class DenseFighterCompatibilityProbe:MonoBehaviour {
 public GameObject acceptedPrefab;public TextAsset proofBytes;DensePoseData data;float cpuError;public GameObject prefab;public int[] fullFootIndices;public Camera captureCamera;public int expectedVertices=1031866;
 GameObject actor;SkinnedMeshRenderer skin;FighterView view;NativeSupportOverlay overlay;CandidateFootGrounding ground;Animator animator;Mesh baked;string dir="NativeDenseEvidence/Fighter/Player";List<string> rows=new List<string>{"state,segment,phase,blend,bodyMode,fullMinimum,proxyMiss,rootXZ"};bool failed;float minimum,maxMiss,maxXZ;int poses;
 IEnumerator Start(){Directory.CreateDirectory(dir);var run=Environment.GetCommandLineArgs().Contains("--dense-current-capacity")?Capacity():Run();float deadline=Time.realtimeSinceStartup+900;while(true){bool more;try{more=run.MoveNext();if(Time.realtimeSinceStartup>deadline)throw new TimeoutException("Dense fighter preview timeout");}catch(Exception e){File.WriteAllText(dir+"/failure.txt",e.ToString());File.WriteAllLines(dir+"/poses.csv",rows);Application.Quit(1);yield break;}if(!more)yield break;yield return run.Current;}}
 IEnumerator Run(){QualitySettings.skinWeights=SkinWeights.Unlimited;actor=Instantiate(prefab);skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();view=actor.GetComponent<FighterView>();overlay=actor.GetComponent<NativeSupportOverlay>();ground=actor.GetComponent<CandidateFootGrounding>();animator=skin.GetComponentInParent<Animator>();if(skin.sharedMesh.vertexCount!=expectedVertices||!animator.avatar.isHuman||!animator.avatar.isValid||!view.UsesNativeMotion)throw new Exception("Playable full-density contract missing");skin.sharedMesh.UploadMeshData(true);skin.forceMatrixRecalculationPerRender=true;var warm=overlay.Warmup();while(warm.MoveNext())yield return warm.Current;baked=new Mesh();data=DensePoseData.Read(proofBytes.bytes);animator.speed=1;
 foreach(var move in Moves.All.Where(m=>animator.HasState(0,Animator.StringToHash("Base Layer."+m.Id)))){for(int step=0;step<4;step++){float phase=(step+.5f)/4;var f=new Fighter{Guard=true};f.Attack=move;f.Frame=Mathf.RoundToInt(phase*(move.Startup+move.Active+move.Recovery));view.PoseTowards(f,new Fighter{X=1,Guard=true},1/60f);yield return new WaitForEndOfFrame();captureCamera.Render();Check(move.Id,"combat");if(step==2&&new[]{"jab","cross","frontKick","sideKick"}.Contains(move.Id))Save(move.Id);}}
 foreach(var entry in overlay.entries){for(int settle=0;settle<8;settle++){view.PoseTowards(new Fighter{Guard=true},new Fighter{X=1,Guard=true},1/60f);yield return new WaitForEndOfFrame();}if(!view.PreviewNativeMotion(entry.state,.275f*entry.pose.duration))throw new Exception("Native preview API missing "+entry.state);animator.speed=1;for(int f=0;f<20;f++){yield return new WaitForEndOfFrame();captureCamera.Render();Check(entry.state,"entry");}for(int f=0;f<8;f++){animator.Play("Base Layer."+entry.state,0,(f+.5f)/8);yield return new WaitForEndOfFrame();captureCamera.Render();Check(entry.state,"holdout");if(f==3)Save(entry.state);}for(int f=0;f<12;f++){view.PoseTowards(new Fighter{Guard=true},new Fighter{X=1,Guard=true},1/60f);yield return new WaitForEndOfFrame();captureCamera.Render();Check(entry.state,"return");}}
 view.PoseTowards(new Fighter{Guard=true},new Fighter{X=1,Guard=true},0);yield return new WaitForEndOfFrame();var mode=actor.GetComponent<OriginalDensityViewMode>();var portraitCenter=animator.GetBoneTransform(HumanBodyBones.Head).position+Vector3.down*.11f;captureCamera.orthographicSize=.42f;captureCamera.transform.position=portraitCenter+actor.transform.rotation*new Vector3(.28f,.12f,1).normalized*6;captureCamera.transform.LookAt(portraitCenter);var portrait=mode.CaptureOriginalPortrait(captureCamera,1024);Write(portrait,dir+"/Master-original-playable-portrait.png");portrait.Release();Destroy(portrait);File.WriteAllLines(dir+"/poses.csv",rows);File.WriteAllText(dir+"/result.json","{\"completed\":true,\"failed\":"+failed.ToString().ToLower()+",\"poses\":"+poses+",\"vertices\":"+expectedVertices+",\"cpuSkinMaximumError\":"+cpuError+",\"minimumSupportY\":"+minimum+",\"maximumProxyMiss\":"+maxMiss+",\"maximumRootXZ\":"+maxXZ+"}");Application.Quit(failed?1:0);}

 IEnumerator Capacity(){Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;QualitySettings.skinWeights=SkinWeights.Unlimited;var perf=new List<string>{"mode,frame,wallMs,renderSubmitMs,mainThreadMs,meshBytes"};var recorder=UnityEngine.Profiling.Recorder.Get("Main Thread");recorder.enabled=true;foreach(string mode in new[]{"accepted100k-HumanGuard","original2m-HumanGuard","original2m-nativeDance"}){var current=Instantiate(mode.StartsWith("accepted")?acceptedPrefab:prefab);var v=current.GetComponent<FighterView>();var o=current.GetComponent<NativeSupportOverlay>();var a=current.GetComponentInChildren<Animator>();var s=current.GetComponentInChildren<SkinnedMeshRenderer>();s.quality=SkinQuality.Auto;s.forceMatrixRecalculationPerRender=true;s.sharedMesh.UploadMeshData(true);var warm=o.Warmup();while(warm.MoveNext())yield return warm.Current;v.PoseTowards(new Fighter{Guard=true},new Fighter{X=1,Guard=true},1);if(mode.EndsWith("Dance"))v.PreviewNativeMotion("Dance",1.5f);a.speed=1;for(int f=0;f<30;f++){yield return new WaitForEndOfFrame();captureCamera.Render();}for(int f=0;f<120;f++){yield return new WaitForEndOfFrame();var timer=System.Diagnostics.Stopwatch.StartNew();captureCamera.Render();timer.Stop();perf.Add(string.Join(",",mode,f,Time.unscaledDeltaTime*1000,timer.Elapsed.TotalMilliseconds,recorder.elapsedNanoseconds/1e6,UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(s.sharedMesh)));}Write(captureCamera.targetTexture,dir+"/capacity-"+mode+".png");File.WriteAllLines(dir+"/quiet-capacity.csv",perf);Destroy(current);yield return null;}File.WriteAllText(dir+"/quiet-capacity-scope.json","{\"completed\":true,\"warmupExplicitRenders\":30,\"measuredExplicitRenders\":120,\"bakeMeshInsideTiming\":false,\"readPixelsInsideTiming\":false,\"sourceReferenceInsideTiming\":false,\"comparisonPrefabsBothLoaded\":true,\"lightShadows\":\"None\"}");Application.Quit(0);}
 void Check(string state,string segment){skin.BakeMesh(baked,true);var v=baked.vertices;if(v.Length!=expectedVertices)throw new Exception("Dense imported vertex count changed");bool body=ReferenceEquals(ground.shoePoints,overlay.defeatBodyPoints);float min=float.PositiveInfinity;if(body){foreach(var p in v)min=Mathf.Min(min,skin.transform.TransformPoint(p).y);}else foreach(int index in fullFootIndices)min=Mathf.Min(min,skin.transform.TransformPoint(v[index]).y);var matrices=data.Matrices(skin.bones);float sampleError=0;for(int k=0;k<v.Length;k+=(segment=="holdout"?1:997))sampleError=Mathf.Max(sampleError,(data.Point(k,matrices)-skin.transform.TransformPoint(v[k])).magnitude);cpuError=Mathf.Max(cpuError,sampleError);float miss=ground.UncorrectedMinimum-(min-ground.LastCorrection);minimum=Mathf.Min(minimum,min);maxMiss=Mathf.Max(maxMiss,miss);var hip=skin.bones.Single(t=>t.name.Substring(t.name.LastIndexOf(':')+1)=="Hips");var p2=animator.transform.InverseTransformPoint(hip.position);float xz=new Vector2(p2.x-overlay.hipBindAnchor.x,p2.z-overlay.hipBindAnchor.z).magnitude;maxXZ=Mathf.Max(maxXZ,xz);if(min<-.0005f||miss>.0005f||xz>1e-5f)failed=true;poses++;rows.Add(string.Join(",",state,segment,overlay.LastSamplePhase,overlay.LastBlendWeight,body,min,miss,xz));if(poses%20==0){File.WriteAllLines(dir+"/poses.csv",rows);File.WriteAllText(dir+"/cpu-diagnostic.json","{\"sampleError\":"+sampleError+",\"maximumError\":"+cpuError+",\"rigY\":"+animator.transform.position.y+",\"rendererY\":"+skin.transform.position.y+",\"correction\":"+ground.LastCorrection+"}");}}
 void Save(string name){Write(captureCamera.targetTexture,dir+"/"+name+".png");}static void Write(RenderTexture rt,string path){var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());RenderTexture.active=old;Destroy(t);}
}
